Geometry loadGeometry(const std::filesystem::path& p,const QByteArray& binding,QString document)noexcept{try{auto g=decodeGeometry(readChecked(p,2*1024*1024),binding);need(g->data["document"].toString()==document,"geometry-document");return g;}catch(...){return {};}}
void saveGeometry(const std::filesystem::path& p,const Geometry& g){need(bool(g),"geometry-null");writeChecked(p,g->data);}
